package com.jadhavr.erp.email.config;
import org.springframework.boot.context.properties.ConfigurationProperties; import org.springframework.stereotype.Component;
@Component @ConfigurationProperties(prefix="app.mail") public class MailProperties {private boolean enabled;private String fromAddress="noreply@localhost",fromName="Jadhavar ERP",replyTo="noreply@localhost";private int maxRetries=3,retryDelaySeconds=60,batchSize=20,tokenExpiryMinutes=30;public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getFromAddress(){return fromAddress;}public void setFromAddress(String v){fromAddress=v;}public String getFromName(){return fromName;}public void setFromName(String v){fromName=v;}public String getReplyTo(){return replyTo;}public void setReplyTo(String v){replyTo=v;}public int getMaxRetries(){return maxRetries;}public void setMaxRetries(int v){maxRetries=v;}public int getRetryDelaySeconds(){return retryDelaySeconds;}public void setRetryDelaySeconds(int v){retryDelaySeconds=v;}public int getBatchSize(){return batchSize;}public void setBatchSize(int v){batchSize=v;}public int getTokenExpiryMinutes(){return tokenExpiryMinutes;}public void setTokenExpiryMinutes(int v){tokenExpiryMinutes=v;}}
